import{_ as t,o as n,c as d,a2 as r}from"./chunks/framework.vLhlLNVn.js";const i="/assets/detailansicht.UGDGbABl.png",m=JSON.parse('{"title":"Einstellungen (Instanz und Datenpunkt)","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/03.referenz/01.einstellungen.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/referenz/einstellungen.md","filePath":"de/adapter/sourceanalytix/referenz/einstellungen.md","lastUpdated":null}'),a={name:"de/adapter/sourceanalytix/referenz/einstellungen.md"};function s(l,e,o,u,c,h){return n(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="einstellungen-instanz-und-datenpunkt" tabindex="-1">Einstellungen (Instanz und Datenpunkt) <a class="header-anchor" href="#einstellungen-instanz-und-datenpunkt" aria-label="Permalink to &quot;Einstellungen (Instanz und Datenpunkt)&quot;">​</a></h1><p><a id="units-supported-energy-volume-weight"></a></p><h2 id="welche-einheiten-werden-unterstutzt-energie-volumen-gewicht-lange" tabindex="-1">Welche Einheiten werden unterstützt (Energie, Volumen, Gewicht, Länge)? <a class="header-anchor" href="#welche-einheiten-werden-unterstutzt-energie-volumen-gewicht-lange" aria-label="Permalink to &quot;Welche Einheiten werden unterstützt (Energie, Volumen, Gewicht, Länge)?&quot;">​</a></h2><p>Leistung, Energie, Volumen, Masse, Länge und Stück. Umgerechnet wird innerhalb derselben Größe und zwischen Litern und Kubikmetern. Leistung und Impulse pro Minute werden über die Zeit aufsummiert.</p><table tabindex="0"><thead><tr><th>Größe</th><th>Einheiten</th><th>Umrechnung in</th></tr></thead><tbody><tr><td>Leistung</td><td><code>GW</code>, <code>MW</code>, <code>kW</code>, <code>W</code>, <code>mW</code></td><td>Energie, über die Zeit aufsummiert</td></tr><tr><td>Energie</td><td><code>GWh</code>, <code>MWh</code>, <code>kWh</code>, <code>Wh</code>, <code>mWh</code></td><td>jede Energie-Einheit</td></tr><tr><td>Volumen</td><td><code>km³</code>, <code>m³</code>, <code>dm³</code>, <code>cm³</code>, <code>mm³</code>, <code>hl</code>, <code>l</code>, <code>dl</code>, <code>cl</code>, <code>ml</code></td><td>jede Volumen-Einheit (1 <code>m³</code> = 1.000 <code>l</code>)</td></tr><tr><td>Masse</td><td><code>t</code>, <code>kg</code>, <code>g</code></td><td>jede Masse-Einheit</td></tr><tr><td>Länge</td><td><code>km</code>, <code>m</code>, <code>dm</code>, <code>cm</code>, <code>mm</code>, <code>µm</code>, <code>nm</code></td><td>jede Länge-Einheit</td></tr><tr><td>Stück</td><td><code>piece</code></td><td>mit „Impulse pro Einheit“ in jede Einheit</td></tr><tr><td>Impulse pro Minute</td><td><code>piece/min</code></td><td>wie <code>piece</code>, über die Zeit aufsummiert</td></tr></tbody></table><p>Am Objekt erkennt SourceAnalytix auch Schreibweisen wie <code>m3</code>, <code>kwh</code>, <code>L</code>, <code>Stk</code> oder <code>pulses/min</code>. Nicht unterstützt sind Zeit (<code>h</code>), Datenmengen, Raten wie <code>m³/h</code> und Größen wie <code>%</code> oder <code>V</code>.</p><h3 id="welche-einheit-gilt-wo" tabindex="-1">Welche Einheit gilt wo? <a class="header-anchor" href="#welche-einheit-gilt-wo" aria-label="Permalink to &quot;Welche Einheit gilt wo?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Einstellung</th><th>Bedeutung</th></tr></thead><tbody><tr><td>„Einheit“ bei der Quelle</td><td>in der der Datenpunkt <strong>liefert</strong>, meist automatisch erkannt</td></tr><tr><td>„Einheit“ in der Preisdefinition</td><td>in der SourceAnalytix <strong>rechnet und anzeigt</strong>; Startwerte und Preis beziehen sich auf sie</td></tr></tbody></table><p>Passen beide nicht zusammen, etwa <code>kg</code> und <code>kWh</code>, startet die Quelle nicht und der Tab „Probleme“ meldet es.</p><h3 id="stuck-und-impulse" tabindex="-1">Stück und Impulse <a class="header-anchor" href="#stuck-und-impulse" aria-label="Permalink to &quot;Stück und Impulse&quot;">​</a></h3><ul><li><strong>Nur zählen</strong>, etwa Brennerstarts: Preisdefinition in <code>piece</code>.</li><li><strong>Impulse in kWh oder m³:</strong> Trage „Impulse pro Einheit“ ein, zum Beispiel <code>1000</code> bei 1000 imp/kWh. Im Assistenten steht das Feld im Schritt „Preis“, in der Detailansicht unter „Einstellungen“.</li><li><strong>Jedes Update ist ein Impuls:</strong> Setze unter „Für Experten“ „Jede Aktualisierung addiert ihren Wert“. Dann zählt jedes Update, auch mit gleichem Wert.</li></ul><p><strong>Siehe auch:</strong> <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Welche Einheit stelle ich am Datenpunkt ein?</a> · <a href="./../fehlerbehebung/log-meldungen#error-unit-not-supported-no">Fehler „No unit defined“</a></p><p><a id="instance-settings-exist-periods-decimals"></a></p><h2 id="welche-instanz-einstellungen-gibt-es-perioden-nachkommastellen" tabindex="-1">Welche Instanz-Einstellungen gibt es (Perioden, Nachkommastellen)? <a class="header-anchor" href="#welche-instanz-einstellungen-gibt-es-perioden-nachkommastellen" aria-label="Permalink to &quot;Welche Instanz-Einstellungen gibt es (Perioden, Nachkommastellen)?&quot;">​</a></h2><p>Vier Tabs. „Haupteinstellungen“ legt fest, welche Wochen-, Monats- und Quartals-States entstehen und wie viele Nachkommastellen neue Quellen bekommen.</p><table tabindex="0"><thead><tr><th>Tab</th><th>Inhalt</th><th>Wirkt</th></tr></thead><tbody><tr><td>„Übersicht“</td><td>alle Quellen mit Werten, „Quelle hinzufügen“, Detailansicht</td><td>Aktionen mit ⚡ sofort</td></tr><tr><td>„Probleme“</td><td>Befunde mit Vorschlag zur Behebung</td><td>sofort</td></tr><tr><td>„Preisdefinitionen“</td><td>Tabelle der Preise</td><td>nach „Speichern“ (Neustart)</td></tr><tr><td>„Haupteinstellungen“</td><td>Perioden und Rundung</td><td>nach „Speichern“ (Neustart)</td></tr></tbody></table><h3 id="tab-„haupteinstellungen" tabindex="-1">Tab „Haupteinstellungen“ <a class="header-anchor" href="#tab-„haupteinstellungen" aria-label="Permalink to &quot;Tab „Haupteinstellungen“&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bereich</th><th>Option</th><th>Standard</th><th>Legt an</th></tr></thead><tbody><tr><td>„Jahresstatistik“</td><td>„Wochen“</td><td>aus</td><td><code>&lt;Jahr&gt;.&lt;Kategorie&gt;.weeks.01</code> bis <code>53</code></td></tr><tr><td>„Jahresstatistik“</td><td>„Monate“</td><td>an</td><td><code>&lt;Jahr&gt;.&lt;Kategorie&gt;.months.01_January</code> bis <code>12_December</code></td></tr><tr><td>„Jahresstatistik“</td><td>„Quartale“</td><td>aus</td><td><code>&lt;Jahr&gt;.&lt;Kategorie&gt;.quarters.Q1</code> bis <code>Q4</code></td></tr><tr><td>„Laufendes Jahr“</td><td>„Wochentag“</td><td>an</td><td><code>currentYear.&lt;Kategorie&gt;.currentWeek.01_Monday</code> bis <code>07_Sunday</code></td></tr><tr><td>„Laufendes Jahr“</td><td>„Wochen“, „Monate“, „Quartale“</td><td>an</td><td><code>currentYear.&lt;Kategorie&gt;.weeks</code>, <code>months</code>, <code>quarters</code></td></tr><tr><td>„Laufendes Jahr“</td><td>„Vorheriger Zeitraum“</td><td>an</td><td><code>01_previousDay</code> bis <code>05_previousYear</code></td></tr><tr><td>„Rundung“</td><td>Nachkommastellen Verbrauch / Kosten</td><td>3 / 2</td><td>Vorlage für neue Quellen</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Schaltest du eine Perioden-Option aus, löscht SourceAnalytix beim Speichern diese States aller Quellen für das laufende Jahr. Die Seite fragt vorher nach. Frühere Jahre und Aufzeichnungen im History-Adapter bleiben.</p></div><p>Fehlt ein State, ist meist die Option aus oder an der Quelle fehlt „Verbrauch“, „Kosten“ oder „Zählerstände speichern“. Vorperioden stehen bis zum ersten Periodenwechsel auf 0.</p><p>Die Nachkommastellen übernimmt jede Quelle einmal beim Anlegen. Danach änderst du sie in der Detailansicht unter „Für Experten“. Erlaubt sind 0 bis 15, -1 heißt ungerundet. <code>cumulativeReading</code> bleibt immer ungerundet.</p><p><strong>Siehe auch:</strong> <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#so-many-decimals">Warum so viele Nachkommastellen?</a> · <a href="./../anleitungen/werte-auswerten#evaluate-across-years-adjusting-everything">Über mehrere Jahre auswerten</a></p><p><a id="datapoint-settings-costs-consumption-meter"></a></p><h2 id="was-bewirken-die-einstellungen-am-datenpunkt-costs-consumption-meter-values" tabindex="-1">Was bewirken die Einstellungen am Datenpunkt (Costs, Consumption, Meter values)? <a class="header-anchor" href="#was-bewirken-die-einstellungen-am-datenpunkt-costs-consumption-meter-values" aria-label="Permalink to &quot;Was bewirken die Einstellungen am Datenpunkt (Costs, Consumption, Meter values)?&quot;">​</a></h2><p>Sie legen fest, was SourceAnalytix für die Quelle rechnet und welche States entstehen. Du findest sie in der Detailansicht der Quelle unter „Einstellungen“; „⚡ Übernehmen“ wirkt sofort.</p><p><img src="'+i+'" alt="Detailansicht einer Quelle mit „Werte“, „Einstellungen“ und „Aktionen“"></p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th><th>Standard</th></tr></thead><tbody><tr><td>„Name“</td><td>Anzeigename, ändert keine State-ID</td><td>Name des Datenpunkts</td></tr><tr><td>„Einheit“</td><td>Einheit, in der der Datenpunkt liefert</td><td>erkannt</td></tr><tr><td>„Preisdefinition“</td><td>Pflicht; Zieleinheit, Kosten oder Erlös</td><td>–</td></tr><tr><td>„Verbrauch“</td><td>States unter <code>consumed</code> oder <code>delivered</code></td><td>an</td></tr><tr><td>„Kosten“</td><td>States unter <code>costs</code> oder <code>earnings</code></td><td>an</td></tr><tr><td>„Grundpreis einrechnen“</td><td>bucht den „Preis pro Monat“</td><td>an, wenn keine andere Quelle ihn bucht</td></tr><tr><td>„Zählerstände speichern“</td><td>Stände je Periode unter <code>meterReadings</code></td><td>an</td></tr><tr><td>„Reset-Erkennung“</td><td>fängt Sprünge auf 0 ab</td><td>aus, bei Shelly und Tasmota an</td></tr><tr><td>„Negative Werte ignorieren“</td><td>nur Leistung: negative Werte zählen als 0</td><td>aus</td></tr><tr><td>„Mittelwert bei Leistung“</td><td>nur Leistung: Mittel aus zwei Werten</td><td>aus</td></tr><tr><td>„Maximale Lücke zwischen Leistungswerten (Minuten)“</td><td>nur Leistung: längere Pausen zählen als 0</td><td>leer = aus</td></tr><tr><td>„Impulse pro Einheit“</td><td>nur Stück: Umrechnung in die Zieleinheit</td><td>leer</td></tr><tr><td>„Startwerte“</td><td>Stand zu Beginn der Perioden</td><td>leer = ab jetzt</td></tr><tr><td>Für Experten: „Schwelle Reset-Erkennung“</td><td>größter Rückgang, der als Schwankung gilt</td><td>1</td></tr><tr><td>Für Experten: „Nachkommastellen“</td><td>Rundung der States</td><td>3 / 2</td></tr><tr><td>Für Experten: „Jede Aktualisierung addiert ihren Wert“</td><td>jedes Update zählt als Zuwachs</td><td>aus</td></tr><tr><td>Für Experten: „Technische ID“</td><td>Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code></td><td>aus dem Namen</td></tr></tbody></table><p>Zahlen gehen mit Komma oder Punkt, ohne Tausendertrennung. Ungültige Felder markiert die Seite und speichert nicht. Löscht eine Änderung Daten, etwa „Verbrauch“ oder „Kosten“ ausschalten oder zwischen „Kosten“ und „Erträge“ wechseln, fragt die Seite vorher mit „Daten löschen?“ nach.</p><p>Am Datenpunkt im Reiter „Objekte“ gibt es nur einen Schalter zum Ein- und Ausschalten. Ausschalten entfernt dort die Einstellungen der Quelle; zum Pausieren nimm „Deaktivieren“.</p><h3 id="wann-meterreadings-leer-bleibt" tabindex="-1">Wann <code>meterReadings</code> leer bleibt <a class="header-anchor" href="#wann-meterreadings-leer-bleibt" aria-label="Permalink to &quot;Wann `meterReadings` leer bleibt&quot;">​</a></h3><p><code>meterReadings</code> enthält den Gesamtstand am Ende einer Periode. Der Ordner bleibt leer, wenn „Zählerstände speichern“ aus ist, die Perioden-Optionen der Instanz aus sind oder der erste Periodenwechsel noch aussteht. Den aktuellen Stand findest du in <code>cumulativeReading</code>.</p><p><strong>Siehe auch:</strong> <a href="./states-und-meldungen#meter-readings-cumulative">Meter-Readings und cumulativeReading</a> · <a href="./../fehlerbehebung/log-meldungen#datapoint-enabled-but-no-folders">Datenpunkt aktiviert, aber keine Ordner</a></p><p><a id="threshold-disabling-reset-detection-work"></a></p><h2 id="wie-funktionieren-threshold-und-abschalten-der-reset-erkennung" tabindex="-1">Wie funktionieren Threshold und Abschalten der Reset-Erkennung? <a class="header-anchor" href="#wie-funktionieren-threshold-und-abschalten-der-reset-erkennung" aria-label="Permalink to &quot;Wie funktionieren Threshold und Abschalten der Reset-Erkennung?&quot;">​</a></h2><p>Beides stellst du je Quelle ein: „Reset-Erkennung“ unter „Einstellungen“, die Schwelle unter „Für Experten“. Die Schwelle (Standard 1, in der Einheit der Preisdefinition) ist der größte Rückgang, der noch als Messschwankung gilt.</p><table tabindex="0"><thead><tr><th>Rückgang</th><th>Reset-Erkennung an</th><th>aus</th></tr></thead><tbody><tr><td>bis zur Schwelle</td><td>wird ignoriert</td><td>Gesamtstand fällt mit</td></tr><tr><td>größer</td><td>SourceAnalytix wartet auf den nächsten Wert und zählt dann weiter</td><td>Gesamtstand fällt, Perioden können negativ werden</td></tr></tbody></table><p>Die Schwelle muss größer sein als das Rauschen des Geräts und kleiner als der Stand, mit dem es nach einem Reset neu beginnt. 0 heißt: Jeder Rückgang ist ein möglicher Reset. Leer gilt als Standard 1.</p><p>Bei Leistung, <code>piece/min</code> und „Jede Aktualisierung addiert ihren Wert“ gibt es keine Reset-Erkennung. Springt eine Quelle ohne Reset-Erkennung auf 0, meldet der Tab „Probleme“ „Zähler springt auf 0, Reset-Erkennung ist aus“ mit „Einschalten“.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">Zähler startet nach Stromausfall bei 0</a> · <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected“?</a></p><p><a id="price-definition-structured-categories-base"></a></p><h2 id="wie-ist-eine-preisdefinition-aufgebaut-kategorien-grundpreis-dezimalzeichen" tabindex="-1">Wie ist eine Preisdefinition aufgebaut (Kategorien, Grundpreis, Dezimalzeichen)? <a class="header-anchor" href="#wie-ist-eine-preisdefinition-aufgebaut-kategorien-grundpreis-dezimalzeichen" aria-label="Permalink to &quot;Wie ist eine Preisdefinition aufgebaut (Kategorien, Grundpreis, Dezimalzeichen)?&quot;">​</a></h2><p>Als Zeile im Tab „Preisdefinitionen“ mit Name („Kategorie“), Einheit, Kostenart und Preis. Jede Quelle hat genau eine. Der Grundpreis wird einmal im Monat voll gebucht, nicht anteilig pro Tag.</p><table tabindex="0"><thead><tr><th>Spalte</th><th>Bedeutung</th></tr></thead><tbody><tr><td>„Kategorie“</td><td>eindeutiger Name, zum Beispiel <code>Strom</code>; nicht leer und nicht doppelt</td></tr><tr><td>„Beschreibung“</td><td>freier Text</td></tr><tr><td>„Kostenart“</td><td>„Kosten“ (<code>consumed</code>, <code>costs</code>) oder „Erträge“ (<code>delivered</code>, <code>earnings</code>)</td></tr><tr><td>„Einheit“</td><td>Einheit, in der gerechnet und angezeigt wird</td></tr><tr><td>„Preisquelle“</td><td>„Festpreis“, „Datenpunkt“ oder „Tarifumschaltung“</td></tr><tr><td>„Preis pro Einheit“</td><td>zum Beispiel <code>0.32</code> für 0,32 €/kWh</td></tr><tr><td>„Preis-Datenpunkt“</td><td>State mit Preis oder Tarif</td></tr><tr><td>„Aktiver Tarifpreis“, „Aktiver Auswahlwert“</td><td>nur bei „Tarifumschaltung“</td></tr><tr><td>„Gültig ab“</td><td>ab 0:00 Uhr dieses Tages gelten die Preise</td></tr><tr><td>„Preis pro Monat“</td><td>Grundpreis</td></tr></tbody></table><p>Komma und Punkt gehen beide, ohne Tausenderpunkt. Ist ein Preis keine Zahl, rechnet SourceAnalytix mit 0 und meldet das im Log. Ob er richtig ankam, zeigt <code>sourceanalytix.0.priceDefinitions.&lt;Kategorie&gt;.currentPrice</code>. Änderungen gelten nach „Speichern“.</p><p>Details zu Preisquellen, „Gültig ab“ und Grundpreis stehen unter <a href="./../anleitungen/preise-und-kosten#costs-recalculated-change-price-change">Preise und Kosten</a>.</p><p><strong>Siehe auch:</strong> <a href="./states-und-meldungen#prices-read-written-as-states">Preise als States</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Kosten bleiben 0</a></p><p><a id="name-datapoint-alias-output-id"></a></p><h2 id="wie-benenne-ich-den-datenpunkt-alias-output-id" tabindex="-1">Wie benenne ich den Datenpunkt (Alias, Output-ID)? <a class="header-anchor" href="#wie-benenne-ich-den-datenpunkt-alias-output-id" aria-label="Permalink to &quot;Wie benenne ich den Datenpunkt (Alias, Output-ID)?&quot;">​</a></h2><p>Eine Quelle hat zwei Namen. Der „Name“ ist nur zur Anzeige und jederzeit änderbar. Die „Technische ID“ ist der Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code> mit allen States; leg sie am besten beim Anlegen fest.</p><p>Der Assistent bildet die Technische ID aus dem Namen, zum Beispiel <code>strom_haus</code> aus „Strom Haus“, und fällt sonst auf die Datenpunkt-ID zurück. Erlaubt sind Buchstaben, Ziffern, <code>_</code> und <code>-</code>. Die ID muss eindeutig sein; <code>info</code>, <code>priceDefinitions</code>, <code>priceHistory</code> und <code>basicPriceHistory</code> sind belegt.</p><p>Änderst du die ID in der Detailansicht unter „Für Experten“, kopiert SourceAnalytix den ganzen Ordner unter die neue ID und löscht danach den alten. Skripte, VIS-Views und History-Abfragen musst du selbst anpassen; alte Aufzeichnungen bleiben unter der alten ID.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#values-consumption-today-yesterday">Wo finde ich meine Werte?</a> · <a href="./../anleitungen/werte-auswerten#read-sourceanalytix-values-script">Werte im Skript lesen</a></p><p><a id="source-types-exist-meter-power"></a></p><h2 id="welche-quelltypen-gibt-es-zahler-leistung" tabindex="-1">Welche Quelltypen gibt es (Zähler, Leistung)? <a class="header-anchor" href="#welche-quelltypen-gibt-es-zahler-leistung" aria-label="Permalink to &quot;Welche Quelltypen gibt es (Zähler, Leistung)?&quot;">​</a></h2><p>Zwei: Ein <strong>Zählerstand</strong> steigt immer weiter, der Verbrauch ist die Differenz. Eine <strong>Leistung</strong> ist ein Momentanwert, den SourceAnalytix über die Zeit aufsummiert. Die Art ergibt sich aus der Einheit.</p><table tabindex="0"><thead><tr><th></th><th>Zählerstand</th><th>Leistung</th></tr></thead><tbody><tr><td>Einheiten</td><td>Energie, Volumen, Masse, Länge, <code>piece</code></td><td>Leistung, <code>piece/min</code></td></tr><tr><td><code>cumulativeReading</code></td><td>Gerätewert + Offset</td><td>beginnt bei 0</td></tr><tr><td>Reset-Erkennung, Startwerte</td><td>ja</td><td>nein</td></tr><tr><td>„Zähler getauscht“</td><td>ja</td><td>nein</td></tr></tbody></table><p>„Jede Aktualisierung addiert ihren Wert“ verhält sich wie eine Leistung. Ob Bezug oder Einspeisung gezählt wird, bestimmt die „Kostenart“ der Preisdefinition.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler oder Leistung?</a> · <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">Watt in kWh</a></p>',58)])])}const p=t(a,[["render",s]]);export{m as __pageData,p as default};
